&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류전형 - 1차 화상면접 - 2차 화상면접 - 최종 합격&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;참고 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;개인정보 처리방침&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;12&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;/span&gt;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.coupang.jobs/kr/privacy-policy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류 반환 정책&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본&lt;/span&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;고지는 『채용절차의공정화에관한법률&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;』&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;제11조제6항에 따른 것 입니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (&lt;/span&gt;&lt;a href=&quot;mailto:recruitingops@coupang.com&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;recruitingops@coupang.com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다. &amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ol&gt;

alphapartners-coupang:greenhouse:7776741.descriptionHtml:
&lt;h2&gt;&lt;strong&gt;Sr. Director, Search AI - Product Engineering&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;We exist to wow our customers. We know we’re doing the right thing when we hear our customers say, “How did we ever live without Coupang?” Born out of an obsession to make shopping, eating, and living easier than ever, we’re collectively disrupting the multi-billion-dollar e-commerce industry from the ground up. We are one of the fastest-growing e-commerce companies that established an unparalleled reputation for being a dominant and reliable force in South Korean commerce.&lt;/p&gt;
&lt;p&gt;We are proud to have the best of both worlds — a startup culture with the resources of a large global public company. This fuels us to continue our growth and launch new services at the speed we have been since our inception. We are all entrepreneurial surrounded by opportunities to drive new initiatives and innovations. At our core, we are bold and ambitious people that like to get our hands dirty and make a hands-on impact. At Coupang, you will see yourself, your colleagues, your team, and the company grow every day.&lt;/p&gt;
&lt;p&gt;Our mission to build the future of commerce is real. We push the boundaries of what’s possible to solve problems and break traditional tradeoffs. Join Coupang now to create an epic experience in this always-on, high-tech, and hyper-connected world.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;About the Role&lt;/h2&gt;
&lt;p&gt;We are looking for a Senior Director to lead and evolve Coupang’s &lt;strong&gt;core search experience&lt;/strong&gt;, powered by cutting-edge AI and machine learning.&lt;/p&gt;
&lt;p&gt;Search is at the heart of Coupang’s customer experience —shaping how millions of customers discover products every day. Improvements in search directly translate into better discovery, higher engagement, and meaningful business impact.&lt;/p&gt;
&lt;p&gt;In this role, you will own the end-to-end search experience - from product direction to ML systems to business outcomes. &amp;nbsp;This role will shape how millions of customers find what they need and lead innovation in AI-powered search at scale and will drive some of the most important metrics in the company.&lt;/p&gt;
&lt;p&gt;This is a high-impact leadership role where you will drive innovation at scale, influence company-wide metrics, and lead a world-class team across engineering and machine learning.&lt;/p&gt;
&lt;h2&gt;What You Will Do&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Own and evolve Coupang’s &lt;strong&gt;search experience&lt;/strong&gt; end-to-end&lt;/li&gt;
&lt;li&gt;Define and execute the &lt;strong&gt;product and technical roadmap&lt;/strong&gt; for search&lt;/li&gt;
&lt;li&gt;Drive measurable impact on key business metrics&lt;/li&gt;
&lt;li&gt;Lead and scale a &lt;strong&gt;multi-layer organization&lt;/strong&gt; across&lt;/li&gt;
&lt;li&gt;Partner closely with Product, Design, and Business leaders to deliver best-in-class customer experiences&lt;/li&gt;
&lt;li&gt;Build and launch &lt;strong&gt;new search capabilities (0→1)&lt;/strong&gt; while continuously improving existing systems&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;What We’re Looking For&lt;/h2&gt;
&lt;h3&gt;Required Qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;10+ years of experience in software engineering and/or machine learning&lt;/li&gt;
&lt;li&gt;Strong product mindset with the ability to connect technical decisions to customer experience and business outcomes&lt;/li&gt;
&lt;li&gt;Strong experience owning &lt;strong&gt;user-facing ML products&lt;/strong&gt; such as:&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Search&lt;/li&gt;
&lt;li&gt;Recommendation systems&lt;/li&gt;
&lt;li&gt;Ads ranking&lt;/li&gt;
&lt;li&gt;Marketplace discovery&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Demonstrated track record of driving &lt;strong&gt;measurable business impact&lt;/strong&gt; (e.g., engagement, conversion, revenue)&lt;/li&gt;
&lt;li&gt;Deep understanding of &lt;strong&gt;search and recommendation systems&lt;/strong&gt;, including:&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Ranking and retrieval&lt;/li&gt;
&lt;li&gt;Relevance and personalization&lt;/li&gt;
&lt;li&gt;System tradeoffs (latency, recall, precision)&lt;/li&gt;
&lt;li&gt;Proven experience leading &lt;strong&gt;large, multi-team organizations&lt;/strong&gt; (including managers of managers)&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred Qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience in e-commerce or marketplace environments&lt;/li&gt;
&lt;li&gt;Experience leading global or multi-region teams&lt;/li&gt;
&lt;li&gt;Experience building 0→1 products or new product surfaces&lt;/li&gt;
&lt;li&gt;Background in fast-scaling consumer technology companies&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Pay &amp;amp; Benefits:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our compensation reflects the cost of labor across several US geographic markets. At Coupang, your base pay is one part of your total compensation. &amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;The base pay for this position ranges from $184,000/year in our lowest geographic market to $376,000/year in our highest geographic market. Pay is based on several factors including market location and may vary depending on job-related knowledge, skills, and experience.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt; &lt;strong&gt;General Description of All Benefits:  &lt;/strong&gt;&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Medical/Dental/Vision/Life, AD&amp;amp;D insurance  &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Flexible Spending Accounts (FSA) &amp;amp; Health Savings Account (HSA)  &lt;/li&gt;
&lt;li&gt;Long-term/Short-term Disability  &lt;/li&gt;
&lt;li&gt;Employee Assistance Program (EAP) program  &lt;/li&gt;
&lt;li&gt;401K Plan with Company Match  &lt;/li&gt;
&lt;li&gt;18-21 days of the Paid Time Off (PTO) a year based on the tenure  &lt;/li&gt;
&lt;li&gt;12 Public Holidays  &lt;/li&gt;
&lt;li&gt;Paid Parental leave  &lt;/li&gt;
&lt;li&gt;Pre-tax commuter benefits  &lt;/li&gt;
&lt;li&gt;MTV - [Free] Electric Car Charging Station&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;General Description of Other Compensation:&lt;/strong&gt;&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;“Other Compensation” includes, but is not limited to, bonuses, equity, or other forms of compensation that would be offered to the hired applicant in addition to their established salary range or wage scale.&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Equal Opportunities for All&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Coupang is an equal opportunity employer. Our unprecedented success could not be possible without the valuable inputs of our globally diverse team.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&amp;nbsp;&lt;/em&gt;&lt;em&gt;Coupang is an equal opportunity employer. All qualified applicants will receive consideration for employment without regard to actual or perceived race (including traits historically associated with race, including but not limited to hair texture and protective hair styles), color, religion, religious creed (including religious dress and grooming practices), sex or gender (including pregnancy, childbirth, breastfeeding, and medical conditions related to pregnancy, childbirth or breastfeeding), gender identity, gender expression, sexual orientation, ,ancestry, national origin (including language use restrictions), age (40 and over), physical or mental disability, medical condition, genetic information, HIV/AIDS or Hepatitis C status, family status (including but not limited to marital or domestic partnership status), military or veteran status, use of a trained dog guide or service animal, political activities or affiliations, ancestry, citizenship, family and medical leave status, status as a victim of any violent crime, or any other characteristic or class protected by the laws or regulations in the locations where we operate. Coupang is also committed to providing a safe work environment for its employees and its consumers.    If you &lt;/em&gt;&lt;em&gt;need assistance and/or reasonable accommodation in the application of recruiting process due to a disability, please contact us at &lt;/em&gt;&lt;a href=&quot;mailto:usrecruiting@coupang.com&quot;&gt;&lt;em&gt;usrecruiting@coupang.com&lt;/em&gt;&lt;/a&gt;&lt;em&gt;.&lt;/em&gt;&lt;em&gt; &lt;/em&gt;&lt;em&gt;&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

alphapartners-coupang:greenhouse:7844556.descriptionHtml:
&lt;p class=&quot;p3&quot;&gt;我們在台灣的包括「火箭速配」，以實惠的價格為多種精選商品提供隔日到貨服務。「火箭跨境」供應來自韓國、美國等地數百萬種暢銷商品，並提供國際速配服務。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;我們正在尋覓人才協助我們帶領 Coupang 台灣拓展業務。這是個難得的機會，一同參與 Coupang 在台灣的成長，打造一個讓我們的顧客自問「沒有 Coupang，我該怎麼過活？」的世界。&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;職位簡介&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;我們正在尋找一位反應敏銳、能獨立作業的選品專案組長，負責推動專案目標並管理一個 5 至 10 人的小團隊。這份工作不僅僅是執行檢查清單，我們更需要一位能全權負責工作流程、洞察細節，並確保團隊維持高生產力與準確性的關鍵人才。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;您將成為產品數據分析與流程改善的技術核心。我們希望您是一位具備主動積極特質的人（Self-starter）——能夠在極少指導下處理複雜任務、主動培訓他人，並在發現瓶頸時找出更好的解決方案。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;核心重點&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 營運所有權：管理每日人力配置，確保團隊達成目標。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 品質管控：維持數據準確性，並在不犧牲品質的前提下提升產出速度。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 獨立分析：自主進行產品研究與屬性對比。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 流程優化：診斷現行標準作業程序 (SOP) 的問題，並提出更聰明的解決方案。&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;主要職責&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 團隊領導與自主管理：以高度責任感帶領 5 至 10 人的團隊；獨立管理專案人力分配與日常營運，確保專案成功。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 績效與考勤管理：監控團隊出勤狀況並進行績效考核，確保所有成員持續達到或超越團隊標準。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 品質與產能管控：監督團隊產出的準確性與效率；主動識別瓶頸，並推動持續改善以確保高質量的數據產出。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 培訓與發展：設計並執行內部培訓計劃，以提升團隊的專業技能與作業效率。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 主管支援：在極少監督的情況下，高效完成主管交辦任務，支援部門整體目標。&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;職位要求&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 產品專業知識：具備強大的產品敏銳度，熟悉品類屬性；能夠獨立進行線上/線下的產品分析與競品研究。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 邏輯思考與適應力：具備嚴謹的邏輯推理能力，能處理複雜數據；作為自驅型人才，需能適應變化，並在動態環境中帶領團隊達成目標。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 高度自主與責任感：證明自己具備獨立作業及在壓力下解決問題的能力；能在多任務環境中有效安排優先順序，確保如期達成目標。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 流程診斷與優化：熟悉 SOP 運作，並具備分析與診斷工作流問題的能力，能獨立提出建設性的優化策略。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 電商熱忱：對電子商務營運與市場趨勢有濃厚興趣，並致力於自我持續成長。&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;加分條件&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 數據處理能力：精通 Excel 進階函數進行數據分析（如：XLOOKUP, COUNTIFS）。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 專業經歷：具備 2 至 3 年行政或專案管理相關經驗。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 培訓與指導經驗：曾有領導、教練或培訓團隊成員以提升整體績效的實績。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 管理背景：具備主管或管理職經驗者優先考慮。&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;招募流程&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 申請資格審核 – 電話面試 – 視訊面試 – 錄取通知&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 招聘流程的確切性質可能會根據具體工作而有所不同，並且可能會因日程安排或其他情況而發生變化。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 面試時間表和結果將透過電子郵件地址通知應徵人員。&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;&lt;strong&gt;需要考慮的事項&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 如果空缺職位已填補，則此職位發布可能會在規定的申請結束日期之前關閉。&lt;/p&gt;
&lt;p class=&quot;p3&quot;&gt;• 如果發現候選人在申請過程中提交了虛假信息，Coupang 有權撤銷聘用邀請。&lt;/p&gt;
&lt;p class=&quot;p4&quot;&gt;&lt;span class=&quot;s1&quot;&gt;• Coupang &lt;/span&gt;不歧視殘疾申請人或退伍軍人。 我們很自豪能為所有申請人提供平等的機會。&lt;/p&gt;

alphapartners-coupang:greenhouse:7971672.descriptionHtml:
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;회사 소개&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;CFS (Coupang Fulfillment Services)는 쿠팡의 물류를 총괄하는 쿠팡의 계열사입니다. CFS는 물류센터 또는 FC (Fulfillment Center) 운영을 책임지고 있으며, 업무 효율성과 전문성 제고를 통해 글로벌 커머스 기업으로 성장하기 위한 혁신을 이끌어 가고 있습니다.&lt;br&gt;&amp;nbsp;&lt;br&gt;쿠팡의 FC는 상품의 입고, 적재, 포장, 출고 및 반품 등 사후 처리에 이르는 다양한 분야의 전문가들이 함께 일하고 있습니다. FC는 단순한 물류 창고와 다르게 공장 자동화 (Factory Automation) 솔루션과 첨단 기술을 활용하고 있습니다. 제조업 생산 공장과 같이 각각의 업무를 전문화하고, 입고부터 출고까지 데이터를 기반으로 시공간을 효율적으로 관리하여 낭비를 최소화하는 등 최적의 물류 시스템을 구현해 나가고 있습니다.&lt;/p&gt;
&lt;p&gt;CFS는 물류 혁신을 통해 고객이 “쿠팡 없이 어떻게 살았을까?” 라고 말하는 세상을 만들고자 합니다. 우리의 역동적인 미래를 함께 만들고 싶다면 CFS와 함께하세요.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직무 소개&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;div class=&quot;ewa-rteLine&quot;&gt;쿠팡의 물류센터 내의 상품 입고, 적재, 포장, 출고 및 인원관리 등 데이터 기반 업무를 수행합니다.&lt;/div&gt;
&lt;div class=&quot;ewa-rteLine&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;ewa-rteLine&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;strong&gt;업무내용&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div class=&quot;ewa-rteLine&quot;&gt;
&lt;ul&gt;
&lt;li&gt;물류센터 오퍼레이션&lt;/li&gt;
&lt;li class=&quot;ewa-rteLine&quot;&gt;물류센터 입/출고 현장 인력 지휘 및 감독&lt;/li&gt;
&lt;li class=&quot;ewa-rteLine&quot;&gt;도급사 커뮤니케이션 담당&lt;/li&gt;
&lt;li class=&quot;ewa-rteLine&quot;&gt;근무조의 안전 및 성과 관리&lt;/li&gt;
&lt;/ul&gt;
&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;자격요건&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;ewa-rteLine&quot;&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;4년 이상의 관련 직무 경험을 보유하신 분&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;물류센터 또는 생산라인 관리 경험을 보유하신 분&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;성과지표 관리와 프로세스 개선 경험을 보유하신 분&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;주/야간 교대근무가 가능하신 분&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;ewa-rteLine&quot;&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;strong&gt;우대사항&lt;/strong&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;50명 이상의 인원관리 경험을 보유하신 분&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;strong&gt;근무지&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;대구 3/7/8 FC: 대구광역시 달성군 구지면 국가산단대로46길 113&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차 및 안내 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류전형 - 전화면접 - 대면(화상)면접 – 최종 합격&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;참고 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;고용형태는 정규직으로 수습기간 12주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;개인정보 처리방침&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;12&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;/span&gt;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.coupang.jobs/kr/privacy-policy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류 반환 정책&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본&lt;/span&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;고지는 『채용절차의공정화에관한법률&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;』&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;제11조제6항에 따른 것 입니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (&lt;/span&gt;&lt;a href=&quot;mailto:recruitingops@coupang.com&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;recruitingops@coupangfs.com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다. &amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;

baincapitalventures-maintainx:greenhouse.descriptionHtml:
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;em&gt;MaintainX est la première plateforme mobile de gestion des procédures pour les travailleurs de l&#39;industrie et les travailleurs de première ligne. Nous construisons le GitHub pour les procédures de travail réelles telles que la maintenance, la sécurité et les opérations, et nous améliorons l&#39;efficacité opérationnelle de plus de 12,000+ entreprises, dont Duracell, Univar Solutions Inc., Titan America, McDonalds, Brenntag, Cintas, Michaels, and Shell.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;em&gt;Nous avons récemment conclu un financement de série D de 150 millions de dollars, ce qui porte notre financement total à 254 millions de dollars et valorise l&#39;entreprise à 2,5 milliards de dollars.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;em&gt;Nous voulons que MaintainX soit la plateforme d&#39;exécution du travail par excellence pour les fabricants, dans les domaines de la maintenance, des opérations et de la sécurité. Pour ce faire, nous mettons en place une nouvelle équipe d&#39;ingénieurs spécialisés dans la recherche afin de développer des systèmes d&#39;indexation et de récupération de données de classe mondiale qui faciliteront la découverte sur l&#39;ensemble de la plateforme.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Ce que vous ferez :&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;66&quot; data-end=&quot;234&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Concevoir, développer et exploiter les API REST publiques de MaintainX, en mettant l’accent sur la cohérence, la scalabilité et une excellente expérience développeur.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;66&quot; data-end=&quot;234&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Mettre en œuvre les standards et bonnes pratiques de la plateforme : authentification/autorisation, limitation de débit (rate limiting), gestion des versions, filtrage, pagination, idempotence, gestion des erreurs et rétrocompatibilité.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;477&quot; data-end=&quot;689&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Concevoir et implémenter des opérations API robustes en batch et en bulk permettant la synchronisation de volumes importants de données et des workflows de migration à grande échelle pour les clients entreprises.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;693&quot; data-end=&quot;958&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Découpler la couche API REST des dépendances monolithiques tout en mettant en place des tests de contrat solides afin de garantir que les évolutions GraphQL n’impactent pas la stabilité des API REST, améliorant ainsi la fiabilité globale et la rapidité d’itération.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;962&quot; data-end=&quot;1138&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Développer des structures de base (scaffolding), des templates et des bibliothèques partagées afin d’accélérer et d’harmoniser le développement des connecteurs et intégrations.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;1142&quot; data-end=&quot;1294&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Améliorer les pipelines CI/CD, l’automatisation des releases et les contrôles qualité (quality gates) pour les intégrations et services de l’écosystème.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;1298&quot; data-end=&quot;1402&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Produire une documentation développeur claire et des implémentations de référence (par exemple des SDK).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;1406&quot; data-end=&quot;1604&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Contribuer à l’infrastructure et aux workflows permettant la publication, la gestion des versions et le support des intégrations sur notre marketplace interne ou externe (par exemple Workato, Tray).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;1608&quot; data-end=&quot;1753&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Mettre en place des parcours d’onboarding automatisés (ex. : création de connexions, gestion des identifiants, configuration des environnements).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;1757&quot; data-end=&quot;1976&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Construire des fondations d’intégration standardisées et des composants réutilisables pour les systèmes d’entreprise (ex. : recettes SAP et composants BTP ; intégrations packagées Oracle EBS/NetSuite et Microsoft D365).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;1980&quot; data-end=&quot;2125&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Garantir que les intégrations répondent aux exigences des entreprises en matière de sécurité, d’auditabilité, de performance et d’exploitabilité.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;2129&quot; data-end=&quot;2350&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Assumer la responsabilité des services en production et des composants de la plateforme de bout en bout : monitoring, astreinte, gestion des incidents, analyse des causes racines et amélioration continue de la robustesse.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;2354&quot; data-end=&quot;2486&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Piloter l’optimisation des performances et de la fiabilité sur la base de données mesurables (SLIs/SLOs, logs, traces et métriques).&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;br&gt;À propos de vous :&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;2518&quot; data-end=&quot;2729&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;4+ années d’expérience professionnelle en ingénierie logicielle, dans le développement de systèmes backend, d’API ou de produits plateforme (le niveau de séniorité reste flexible selon l’impact et le périmètre).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;2733&quot; data-end=&quot;2932&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Solide expérience en développement backend orienté services et maîtrise d’au moins l’un des langages suivants : TypeScript, Go ou C#, avec une volonté d’apprendre d’autres langages selon le contexte.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;2936&quot; data-end=&quot;3113&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Forte expérience avec les bases de données relationnelles (ex. MySQL, PostgreSQL), incluant la conception de schémas, l’optimisation des requêtes et la modélisation des données.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;3117&quot; data-end=&quot;3242&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Bonne compréhension des fondamentaux des systèmes distribués : fiabilité, scalabilité, cohérence et gestion des défaillances.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;3246&quot; data-end=&quot;3389&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Expérience dans la mise en production d’API robustes et réflexion approfondie sur l’expérience développeur et l’utilisabilité de la plateforme.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;3393&quot; data-end=&quot;3526&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Forte culture du testing (tests unitaires, d’intégration, end-to-end et tests de contrat) et expérience pratique des pipelines CI/CD.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;3530&quot; data-end=&quot;3751&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;À l’aise dans la collaboration transverse avec les équipes Produit, Design et les équipes en contact avec les clients, tout en restant focalisé sur des solutions produit scalables (et non des implémentations ponctuelles).&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;br&gt;Atouts supplémentaires:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;div class=&quot;job__description body&quot;&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;3789&quot; data-end=&quot;3942&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Expérience avec les écosystèmes d’intégration : plateformes API, SDK, iPaaS/connecteurs, marketplaces, webhooks/événements, patterns ETL/synchronisation.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;3946&quot; data-end=&quot;4100&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Connaissance des modèles d’identité et de sécurité en environnement entreprise (OAuth2/OIDC, clés API, rotation de tokens, principe du moindre privilège).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;4104&quot; data-end=&quot;4213&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Expérience avec les écosystèmes ERP (SAP S/4HANA ou ECC 6, SAP BTP, Oracle EBS/NetSuite, Microsoft Dynamics).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;4217&quot; data-end=&quot;4339&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Expérience dans le développement d’outils d’administration et de debug en self-service pour développeurs externes/clients.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot; data-start=&quot;4343&quot; data-end=&quot;4580&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Expérience avec Workato, Tray ou Zapier du point de vue ingénierie produit/plateforme (ex. : création de connecteurs, et non uniquement de recettes, workflows ou zaps — bien qu’une familiarité avec ces éléments soit également appréciée).&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;br&gt;Ce que nous vous offrons:&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Un salaire compétitif et des opportunités d&#39;équité significatives.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Couverture des soins de santé, des soins dentaires et des soins de la vue.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Programme d&#39;inscription 401(k) / RRSP.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Prenez les congés dont vous avez besoin.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Une&amp;nbsp;&lt;a href=&quot;https://crew.vc/perspectives-insights/scaling-culture-through-hyper-growth/&quot;&gt;culture&lt;/a&gt;&amp;nbsp;du travail où:&lt;/span&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous travaillerez aux côtés de personnes du monde entier qui reflètent les valeurs de MaintainX : Intelligents, Humbles, Optimistes.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Nous croyons en la méritocratie, où les idées et les efforts sont publiquement célébré.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;&lt;/div&gt;
